insert into public.ideas (id, organization_id, author_id, author_name, author_email, title, original_description, structured_proposal, area, status, analysis, priority, responsible_id, created_at, submitted_at) values
(md5('nuevo-demo:idea:vale-claro:0')::uuid, md5('nuevo-demo:org:vale-claro')::uuid, md5('nuevo-demo:author:vale-claro:0')::uuid, 'Marina Teixeira', 'marina.teixeira@example.com', 'Reaproveitar a água da lavagem de caixas', 'Na lavagem das caixas usamos muita água limpa que vai direto para o esgoto. Hoje gastamos uns 40 m3 por dia. Sugiro instalar um filtro e reutilizar essa água na primeira etapa da lavagem, e medir o consumo com um medidor. Meta de reduzir 20% em 3 meses. A manutenção seria responsável.', '{"title":"Reaproveitar a água da lavagem de caixas","problem":null,"solution":null,"context":null,"beneficiaries":null,"esgDimensions":null,"expectedBenefits":null,"indicators":null,"resourcesAndRisks":null,"nextSteps":null,"source":"manual","updatedAt":"2026-06-02T16:00:00.000Z"}'::jsonb, 'Produção', 'implemented', '{"method":"motor_local","notice":"Classificação preliminar por regras, sem IA externa. Os escores são heurísticos, não probabilidades, e não aprovam a ideia nem comprovam impacto.","status":"submitted","dimensions":[{"dimension":"E","hits":["água limpa","reutilizar essa água","esgoto","água"],"explanation":"O texto menciona recursos naturais, energia, resíduos ou emissões."}],"suggestedMetrics":["Consumo de energia (kWh)","Consumo de água (m³)","Resíduos desviados de aterro (kg)"],"criteriaVersionId":null,"criteriaVersionLabel":"Dados de demonstração","local":{"classification":{"status":"classified","primary_pillar":"E","secondary_pillars":[],"subcategories":["E2"],"matches":[{"rule_id":"e2-consumo-agua","subcategory":"E2","matched_text":"água limpa","score":3,"negated":false,"explanation":"Trata de consumo ou desperdício de água."},{"rule_id":"e2-reuso","subcategory":"E2","matched_text":"reutilizar essa água","score":3,"negated":false,"explanation":"Trata de reúso ou captação de água."},{"rule_id":"e2-efluentes","subcategory":"E2","matched_text":"esgoto","score":3,"negated":false,"explanation":"Trata de efluentes ou qualidade da água."},{"rule_id":"e2-agua","subcategory":"E2","matched_text":"água","score":1,"negated":false,"explanation":"Menciona água, sem detalhar o uso."}],"match_score":0.79,"match_score_type":"heuristic_not_probability","needs_human_review":false,"review_reasons":[],"missing_information":["quem é afetado"],"signals":{"action":true,"problem":true,"audience":false,"baseline":true,"target":true,"measurement":true,"resources":true,"responsibility":true,"deadline":true,"cost":false,"benefit":true,"scale":false,"innovation":false,"strategy":false,"evidence":false,"critical":false,"quantity":true,"money":false},"engine_version":"2.0.0","lexicon_version":"lexico-2.0.0"},"assessment":{"criteria":[{"code":"C1","grade":3,"reason":"evidence_in_text","justification":"Há ação, números de referência e forma de medir. O impacto ainda precisa ser comprovado."},{"code":"C2","grade":4,"reason":"evidence_in_text","justification":"Indica recursos, responsáveis e prazo."},{"code":"C3","grade":null,"reason":"insufficient_information","justification":"Pendente: o texto não informa custos nem orçamento."},{"code":"C4","grade":null,"reason":"insufficient_information","justification":"Pendente: o texto não informa o que muda em relação ao que já é feito."},{"code":"C5","grade":null,"reason":"insufficient_information","justification":"Pendente: o texto não informa relação com objetivos da empresa; a gestão avalia este critério."},{"code":"C6","grade":4,"reason":"evidence_in_text","justification":"Traz forma de medir, número de referência e meta."},{"code":"C7","grade":null,"reason":"insufficient_information","justification":"Pendente: o texto não informa se pode ser replicada ou ampliada."},{"code":"C8","grade":4,"reason":"evidence_in_text","justification":"A proposta descreve 4 de 5 elementos: problema, ação, público, medição e recursos."}],"score":null,"partial_score":71.66666666666667,"assessed_weight":60,"pending_criteria":["C3","C4","C5","C7"]}}}'::jsonb, 'alta', md5('nuevo-demo:manager:vale-claro')::uuid, '2026-