-- População de demonstração: 5 empresas e 25 ideias FICTÍCIAS. Gerado por generate_seed_demo.mjs.
-- Antes de rodar, troque a senha abaixo: ela vale para os 5 gestores e o repositório é público.
-- Prévia: rode com "rollback;" no lugar do "commit;" do fim do arquivo.
-- Pode rodar de novo sem duplicar. Para desfazer: supabase/scripts/rollback_seed_demo.sql.
begin;

create or replace function pg_temp.demo_manager(p_id uuid, p_email text, p_password text) returns void language plpgsql as $$
begin
  if exists (select 1 from auth.users where id = p_id) then return; end if;
  values ('00000000-0000-0000-0000-000000000000', p_id, 'authenticated', 'authenticated', p_email,
    extensions.crypt(p_password, extensions.gen_salt('bf')), now(), false,
    '{"provider":"email","providers":["email"]}'::jsonb, '{}'::jsonb, now(), now(), '', '', '', '');
  values (p_id::text, p_id, jsonb_build_object('sub', p_id::text, 'email', p_email, 'email_verified', true), 'email', now(), now(), now());
end;
$$;

do $$
declare
  v_password text := 'TROQUE_ESTA_SENHA';
begin
  if v_password = 'TROQUE_ESTA_SENHA' then
    raise exception 'Troque a senha na variável v_password antes de rodar.';
  end if;
  perform pg_temp.demo_manager(md5('nuevo-demo:manager:vale-claro')::uuid, 'gestor@vale-claro.example.com', v_password);
  perform pg_temp.demo_manager(md5('nuevo-demo:manager:ferrolinea')::uuid, 'gestor@ferrolinea.example.com', v_password);
  perform pg_temp.demo_manager(md5('nuevo-demo:manager:rota-verde')::uuid, 'gestor@rota-verde.example.com', v_password);
  perform pg_temp.demo_manager(md5('nuevo-demo:manager:bem-cuidar')::uuid, 'gestor@bem-cuidar.example.com', v_password);
  perform pg_temp.demo_manager(md5('nuevo-demo:manager:ponte-alta')::uuid, 'gestor@ponte-alta.example.com', v_password);
end;
$$;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (user_id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

select
  (select count(*) from public.organizations where id in (md5('nuevo-demo:org:vale-claro')::uuid, md5('nuevo-demo:org:ferrolinea')::uuid, md5('nuevo-demo:org:rota-verde')::uuid, md5('nuevo-demo:org:bem-cuidar')::uuid, md5('nuevo-demo:org:ponte-alta')::uuid)) as empresas,
  (select count(*) from public.ideas where id::text in (select md5('nuevo-demo:idea:' || c || ':' || n)::uuid::text from unnest(array['vale-claro', 'ferrolinea', 'rota-verde', 'bem-cuidar', 'ponte-alta']) c, generate_series(0, 4) n)) as ideias;

commit;
